import Link from "next/link"

import { buttonVariants } from "@/components/ui/button"
import { ArrowButton } from "@/components/tybow/arrow-button"
import { FlushPhoto } from "@/components/tybow/flush-photo"
import { cn } from "@/lib/utils"

export type ChapterProps = {
  id?: string
  eyebrow: string
  line: string
  copy?: string
  photo?: { src?: string; alt: string }
  cta?: { href: string; label: string }
  secondaryCta?: { href: string; label: string }
  layout?: "stacked" | "split"
  /** Split only. Alternate photo side; still one layout, not a third variant. */
  photoSide?: "start" | "end"
  /** Paper sits beside the photo. Flush puts type on the photo, Pines-style. */
  tone?: "paper" | "flush"
}

export function Chapter({
  id,
  eyebrow,
  line,
  copy,
  photo,
  cta,
  secondaryCta,
  layout = "stacked",
  photoSide = "end",
  tone = "paper",
}: ChapterProps) {
  const flush = tone === "flush" && layout === "stacked" && Boolean(photo)

  const visual = photo ? (
    <div
      className={cn(
        "relative overflow-hidden",
        flush
          ? "absolute inset-0 rounded-none"
          : layout === "split"
            ? "aspect-[4/3] rounded-lg"
            : "aspect-[16/9] rounded-lg",
        !flush && layout === "split" && photoSide === "start" && "lg:order-first",
      )}
    >
      <FlushPhoto
        src={photo.src}
        alt={photo.alt}
        className="absolute inset-0 size-full"
      />
    </div>
  ) : null

  const copyBlock = (
    <div className={cn(flush && "relative z-10 max-w-xl")}>
      <p
        className={cn(
          "text-xs font-semibold tracking-[0.2em] uppercase",
          flush ? "text-primary-foreground" : "text-muted-foreground",
        )}
      >
        {eyebrow}
      </p>
      <h2
        className={cn(
          "mt-3 font-display font-medium tracking-[-0.045em] text-balance",
          flush
            ? "text-[length:var(--display-hero,var(--display-size))] leading-[0.88] text-primary-foreground"
            : "max-w-[16ch] text-display leading-[1.05] text-foreground",
        )}
      >
        {line}
      </h2>
      {copy ? (
        <p
          className={cn(
            "mt-4 max-w-md text-pretty",
            flush ? "text-primary-foreground/90" : "text-foreground",
          )}
        >
          {copy}
        </p>
      ) : null}
      {cta || secondaryCta ? (
        <div className={cn("flex flex-wrap items-center gap-3", flush ? "mt-8" : "mt-10")}>
          {cta ? (
            flush ? (
              <ArrowButton href={cta.href} variant="cream">
                {cta.label}
              </ArrowButton>
            ) : (
              <Link
                href={cta.href}
                className={buttonVariants({ variant: "default", size: "lg" })}
              >
                {cta.label}
              </Link>
            )
          ) : null}
          {secondaryCta ? (
            flush ? (
              <ArrowButton href={secondaryCta.href} variant="ghost">
                {secondaryCta.label}
              </ArrowButton>
            ) : (
              <Link
                href={secondaryCta.href}
                className={buttonVariants({ variant: "outline", size: "lg" })}
              >
                {secondaryCta.label}
              </Link>
            )
          ) : null}
        </div>
      ) : null}
    </div>
  )

  if (flush) {
    return (
      <section
        id={id}
        className="relative isolate flex min-h-svh flex-col justify-end overflow-hidden bg-primary"
      >
        {visual}
        <div
          className="absolute inset-0 bg-primary/35"
          aria-hidden="true"
        />
        <div className="relative z-10 px-[7vw] pt-32 pb-16">{copyBlock}</div>
      </section>
    )
  }

  return (
    <section id={id} className="bg-background">
      <div
        className={cn(
          "mx-auto max-w-[1400px] px-[7vw] py-section",
          layout === "split" &&
            "grid items-start gap-12 lg:grid-cols-2 lg:gap-20",
        )}
      >
        {copyBlock}
        {layout === "stacked" ? <div className="mt-10">{visual}</div> : visual}
      </div>
    </section>
  )
}

import type { ComponentProps, ReactNode } from "react"

import { cn } from "@/lib/utils"

function ArrowIcon() {
  return (
    <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden>
      <path
        d="M3 8h10M9 4l4 4-4 4"
        stroke="currentColor"
        strokeWidth="1.4"
        strokeLinecap="square"
      />
    </svg>
  )
}

export type ArrowButtonProps = {
  variant?: "cream" | "inverse" | "ghost"
  href?: string
  className?: string
  children: ReactNode
} & Omit<ComponentProps<"button">, "className">

export function ArrowButton({
  variant = "cream",
  href,
  className,
  children,
  type = "button",
  ...props
}: ArrowButtonProps) {
  const classes = cn(
    "inline-flex min-h-[3.25rem] items-center gap-3 pr-1.5 pl-5 font-sans text-[0.92rem] font-semibold tracking-[0.04em] uppercase",
    variant === "cream" &&
      "bg-primary-foreground text-foreground shadow-[0_10px_28px_color-mix(in_oklch,var(--foreground)_32%,transparent)]",
    variant === "inverse" && "bg-primary text-primary-foreground",
    variant === "ghost" &&
      "min-h-[3.25rem] border-[1.5px] border-primary-foreground bg-foreground/60 px-5 text-primary-foreground",
    className,
  )

  const iconWrap =
    variant === "ghost" ? null : (
      <span
        className={cn(
          "grid size-9 place-items-center",
          variant === "cream" && "bg-primary text-primary-foreground",
          variant === "inverse" && "bg-primary-foreground text-primary",
        )}
      >
        <ArrowIcon />
      </span>
    )

  const inner = (
    <>
      {children}
      {iconWrap}
    </>
  )

  if (href) {
    return (
      <a href={href} className={classes}>
        {inner}
      </a>
    )
  }

  return (
    <button type={type} className={classes} {...props}>
      {inner}
    </button>
  )
}

import { cn } from "@/lib/utils"

export type FlushPhotoProps = {
  src?: string
  alt: string
  label?: string
  fit?: "cover" | "contain"
  className?: string
}

export function FlushPhoto({
  src,
  alt,
  label = "replace with client photo",
  fit = "cover",
  className,
}: FlushPhotoProps) {
  return (
    <div className={cn("relative overflow-hidden bg-muted", className)}>
      {src ? (
        // Parent owns crop and radius. No inner mat.
        // eslint-disable-next-line @next/next/no-img-element
        <img
          src={src}
          alt={alt}
          className={cn(
            "absolute inset-0 size-full",
            fit === "contain" ? "object-contain" : "object-cover",
          )}
        />
      ) : (
        <div
          className="absolute inset-0 flex items-center justify-center bg-muted px-6 text-center"
          role="img"
          aria-label={alt}
        >
          <p className="text-sm text-muted-foreground">{label}</p>
        </div>
      )}
    </div>
  )
}
